    }

    private boolean isDescendant(Element node, Element ancestor) {
        Node parent = node.parentNode();
        while (parent != null) {
            if (parent == ancestor) return true;
            parent = parent.parentNode();
        }
        return false;
    }

    @Override
    public FormElement clone() {
        return (FormElement) super.clone();
    }
