@Override
public FormElement clone() {
    FormElement clone = (FormElement) super.clone();
    // Object.clone shares the parser-linked list; give the clone its own, dropping links that belong to another
    // document (the deep child clone has its own matching control instances)
    Document cloneOwner = clone.ownerDocument();
    Elements linked = new Elements();
    for (Element linkedEl : clone.linkedEls) {
        if (linkedEl.ownerDocument() == cloneOwner) linked.add(linkedEl);
    }
    clone.linkedEls.clear();
    clone.linkedEls.addAll(linked);
    return clone;
}

